/*
 * Host test for the only part of the probe checkable without a radio.
 *
 * Vectors are generated by the project's own Python reference codec, not written by hand, so
 * they are real encodings rather than something shaped like one.
 */
#include <assert.h>
#include <stdio.h>
#include <string.h>

#include "../src/dmd_sniff.h"

/* encode_group(...1 rider...)  -> d2 03 02 00 */
#define GROUP_PKT "0gMCAKP5AAGcVFFiP3GeM60GtnAXm7jSjtAKWw"
/* encode_chat(...)             -> d2 03 02 01 */
#define CHAT_PKT  "0gMCAaP5AAKcVFFimemT83ck12LCPw"

static dmd_sniff_t sniff_str(const char *s) {
    return dmd_sniff((const unsigned char *)s, strlen(s));
}

int main(void) {
    dmd_sniff_t r = sniff_str(GROUP_PKT);
    assert(r.found && r.offset == 0);
    assert(r.version == 3 && r.ttl == 2 && r.type == 0);

    r = sniff_str(CHAT_PKT);
    assert(r.found && r.type == 1);

    /*
     * The reason the header is decoded rather than trusting the "0g" prefix: those two
     * characters pin the magic and the top nibble of the version only, so a long run of
     * plausible base64 starting "0g" decodes to D2 00 - right magic, version 0, not a packet.
     * This is the case the first version of this recognizer accepted.
     */
    assert(!sniff_str("0gAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA").found);

    /* Marker at the very end of a long run has no packet behind it. */
    assert(!sniff_str("QUJDREVGR0hJSktMTU5PUFFSU1RVVldYWVo0g").found);

    /* Framing around the payload is a finding, not a miss: the offset says how much. */
    r = sniff_str("\x01\x02XYZ" GROUP_PKT);
    assert(r.found);
    assert(r.offset - r.run_start == 3);
    assert(r.version == 3);

    /* Too short to be anything, even with the right prefix. */
    assert(!sniff_str("0g").found);
    assert(!sniff_str("junk0gjunk").found);

    /* Printable and long, but another protocol. */
    assert(!sniff_str("HelloThisIsSomeOtherProtocolEntirely").found);

    /* Non-printable noise of any length. */
    unsigned char noise[64];
    for (int i = 0; i < 64; i++) noise[i] = (unsigned char)(i * 7 + 3);
    assert(!dmd_sniff(noise, sizeof noise).found);

    printf("dmd payload recognition      ok\n");
    return 0;
}
